import {SqliteAgentRuns,SqliteAgentDefinitions,DurableAgentWorker} from '../../dist/index.js';
import {TracerProvider,SimpleSpanProcessor,InMemorySpanExporter} from '@opentelemetry/sdk-trace';
const exporter=new InMemorySpanExporter(),provider=new TracerProvider({spanProcessors:[new SimpleSpanProcessor({exporter})]}),runs=new SqliteAgentRuns(process.env.TEST_RUNS),definitions=new SqliteAgentDefinitions(process.env.TEST_DEFINITIONS);
try{const worker=new DurableAgentWorker({runs,definitions,workerId:'worker',leaseMs:10000,pollMs:100,authorizeStart:()=>true,execute:async()=> 'succeeded',tracing:{tracer:provider.getTracer('worker'),usePersistedParent:true}});await worker.runOnce({tenantId:'tenant',agentId:'agent'},process.env.TEST_RUN_ID);const span=exporter.getFinishedSpans()[0];process.stdout.write(JSON.stringify({traceId:span.spanContext().traceId,parent:span.parentSpanContext.spanId,status:span.attributes['app_mixer.agent.run.status']}));}finally{runs.close();definitions.close();await provider.shutdown();}
